-- id:       exists-repeat-escalations
-- title:    Complaints escalated twice or more
-- concept:  Correlated EXISTS with aggregate
-- rubric:   7 · Correlated queries
-- purpose:  EXISTS runs once per complaint row and checks its own escalation count.
-- GENERATED by web/scripts/export-queries.ts from src/lib/data/mock/lab.ts. Edit there, then run npm run db:queries.

SELECT c.complaint_id, c.title, w.ward_name, c.status
FROM complaint c
JOIN ward w USING (ward_id)
WHERE EXISTS (SELECT 1 FROM escalation e
              WHERE e.complaint_id = c.complaint_id
              GROUP BY e.complaint_id
              HAVING COUNT(*) >= 2)
ORDER BY c.complaint_id;
